  type RecordAnswerInput,
  recordAnswerInput,
} from '@emotely/contract';
import {
  generateText,
  isStepCount,
  type JSONValue,
  type LanguageModel,
  type ModelMessage,
  tool,
} from 'ai';

export type Question = {
  id: string;
  text: string;
  answer_type: AnswerType;
  min_answers?: number;
