131	            toolCallId: call.toolCallId,
132	            toolName: call.toolName,
133	            output: { type: "json", value: { answer: value } },
134	          },
135	        ],
136	      });
137	    }
138	  }
139	
140	  return { summary, answers, usage, messages, promptId: PROMPT_ID };
141	}

14	  ],
15	});
