1	import {
2	  type Answer,
3	  type AnswerType,
4	  type AskQuestionInput,
5	  askQuestionInput,
6	  completeSessionInput,
7	  recordAnswerInput,
8	} from "@emotely/contract";
9	import {
10	  generateText,
11	  isStepCount,
12	  type JSONValue,
13	  type LanguageModel,
14	  type LanguageModelUsage,
15	  type ModelMessage,
16	  tool,
17	} from "ai";
18	import type { TokenUsage } from "./cost.ts";
19	import { PROMPT_ID, sessionPrompt } from "./session-prompt.ts";
20	import { PRIVACY_TELEMETRY } from "./telemetry.ts";
21	
22	type ListAnswerType = Extract<AnswerType, "color" | "emoji" | "text_list">;
23	type ScalarAnswerType = Exclude<AnswerType, ListAnswerType>;
24	
25	// Union on answer_type so min_answers only exists where the value is a list.
26	export type Question = { id: string; text: string } & (
27	  | { answer_type: ScalarAnswerType; min_answers?: never }
28	  | { answer_type: ListAnswerType; min_answers?: number }
29	);
30	
31	export type QuestionSet = {
32	  id: string;
33	  name: string;
34	  questions: Question[];
35	};
36	
37	export type SessionClient = {
38	  /** Answer an ask_question tool call with the raw widget value. */
39	  askQuestion: (input: AskQuestionInput) => Promise<JSONValue>;
40	};
41	
42	export type SessionResult = {
43	  summary: string;
44	  answers: Record<string, Answer>;
45	  /** Token totals across every model round, for cost accounting. */
46	  usage: TokenUsage;
47	  /** The full conversation, for eval transcripts and debugging. */
48	  messages: ModelMessage[];
49	  /** Version id of the system prompt this session ran with. */
50	  promptId: string;
51	  /** Wall-clock ms per model round — what the user waits between widgets. */
52	  roundLatenciesMs: number[];
53	};
54	
55	// ponytail: generous cap — a poweruser recording 20 gratitudes must never hit
56	// it; tighten with real usage data once PostHog is wired (issue #5).
57	const MAX_ROUNDS_PER_QUESTION = 6;
58	const ROUND_SLACK = 20;
59	
60	function buildSessionTools(
61	  questionSet: QuestionSet,
62	  answers: SessionResult["answers"],
63	  asked: Set<string>,
64	  onComplete: (summary: string) => void,
65	) {
66	  return {
67	    ask_question: tool({
68	      description:
69	        "Ask the user one journaling question; the client renders the widget.",
70	      inputSchema: askQuestionInput,
71	      // no execute: client-side tool — the session loop supplies the result
72	    }),
73	    record_answer: tool({
74	      description: "Record the validated answer for one question.",
75	      inputSchema: recordAnswerInput,
76	      execute: async ({ question_id, answer }) => {
77	        const question = questionSet.questions.find(
78	          (q) => q.id === question_id,
79	        );
80	        const min = question?.min_answers ?? 1;
81	        if (Array.isArray(answer.value) && answer.value.length < min) {
82	          return {
83	            recorded: false,
84	            error: `This question needs at least ${min} answers.`,
85	          };
86	        }
87	        answers[question_id] = answer;
88	        return { recorded: true };
89	      },
90	    }),
91	    complete_session: tool({
92	      description: "Finish the session with a summary of the journal entry.",
93	      inputSchema: completeSessionInput,
94	      execute: async ({ summary }) => {
95	        // Models tend to skip record_answer for the final question; an asked
96	        // question without a recorded answer is a lost answer, so refuse.
97	        const unrecorded = [...asked].filter((id) => !(id in answers));
98	        if (unrecorded.length > 0) {
99	          return {
100	            completed: false,
101	            error: `Record the answer for ${unrecorded.join(", ")} with record_answer before completing.`,
102	          };
103	        }
104	        onComplete(summary);
105	        return { completed: true };
106	      },
107	    }),
108	  };
109	}
110	
111	function addUsage(total: TokenUsage, step: LanguageModelUsage): void {
112	  total.inputTokens += step.inputTokens ?? 0;
113	  total.cacheReadTokens += step.inputTokenDetails.cacheReadTokens ?? 0;
114	  total.outputTokens += step.outputTokens ?? 0;
115	}
116	
117	/** Client-executed tool: the client answers ask_question with the widget value. */
118	async function answerAskQuestion(
119	  call: { toolCallId: string; toolName: string; input: unknown },
120	  client: SessionClient,
121	  asked: Set<string>,
122	): Promise<ModelMessage> {
123	  const input = call.input as AskQuestionInput;
124	  asked.add(input.question_id);
125	  const value = await client.askQuestion(input);
126	  return {
127	    role: "tool",
128	    content: [
129	      {
130	        type: "tool-result",
131	        toolCallId: call.toolCallId,
132	        toolName: call.toolName,
133	        output: { type: "json", value: { answer: value } },
134	      },
135	    ],
136	  };
137	}
138	
139	/** Generous round cap so a model that never completes cannot loop forever. */
140	function roundGuard(questionSet: QuestionSet): { next: () => void } {
141	  const maxRounds =
142	    questionSet.questions.length * MAX_ROUNDS_PER_QUESTION + ROUND_SLACK;
143	  let rounds = 0;
144	  return {
145	    next: () => {
146	      if (++rounds > maxRounds) {
147	        throw new Error(
148	          `Session round limit reached (${maxRounds}) without complete_session.`,
149	        );
150	      }
151	    },
152	  };
153	}
154	
155	export async function runSession(opts: {
156	  questionSet: QuestionSet;
157	  client: SessionClient;
158	  model: LanguageModel;
159	  /** Sampling temperature; evals pin 0 for stability, product uses default. */
160	  temperature?: number;
161	}): Promise<SessionResult> {
162	  const { questionSet, client, model, temperature } = opts;
163	  const answers: SessionResult["answers"] = {};
164	  const asked = new Set<string>();
165	  const roundLatenciesMs: number[] = [];
166	  const usage: TokenUsage = {
167	    inputTokens: 0,
168	    cacheReadTokens: 0,
169	    outputTokens: 0,
170	  };
171	  let summary: string | undefined;
172	
173	  const tools = buildSessionTools(questionSet, answers, asked, (s) => {
174	    summary = s;
175	  });
176	
177	  const messages: ModelMessage[] = [
178	    { role: "user", content: "I am ready to start my journaling session." },
179	  ];
180	
181	  const guard = roundGuard(questionSet);
182	
183	  while (summary === undefined) {
184	    guard.next();
185	    const startedAt = performance.now();
186	    const result = await generateText({
187	      model,
188	      instructions: sessionPrompt(questionSet),
189	      tools,
190	      stopWhen: isStepCount(1),
191	      ...(temperature === undefined ? {} : { temperature }),
192	      telemetry: PRIVACY_TELEMETRY,
193	      messages,
194	    });
195	    roundLatenciesMs.push(performance.now() - startedAt);
196	    messages.push(...result.response.messages);
197	    addUsage(usage, result.usage);
198	
199	    if (result.finishReason !== "tool-calls") {
200	      continue;
201	    }
202	
203	    for (const call of result.toolCalls) {
204	      if (call.toolName === "ask_question") {
205	        messages.push(await answerAskQuestion(call, client, asked));
206	      }
207	    }
208	  }
209	
210	  return {
211	    summary,
212	    answers,
213	    usage,
214	    messages,
215	    promptId: PROMPT_ID,
216	    roundLatenciesMs,
217	  };
218	}

